        print("model:", d.get('model'), "reasoningEffort:", d.get('reasoningEffort'), "interactionMode:", d.get('interactionMode'), "autonomyLevel:", d.get('autonomyLevel'))
        break
# timestamp format + seq type
f = sorted(glob.glob('*.jsonl'), key=os.path.getmtime)[-1]
for line in open(f, errors='replace'):
    o=json.loads(line)
    if o.get('type')=='message':
        print("timestamp sample type:", type(o['timestamp']).__name__, "len", len(str(o['timestamp'])), "seq type", type(o.get('seq')).__name__); break
for line in open(f, errors='replace'):
