    if o.get('type')=='agent_turn_outcome':
        print("agent_turn_outcome resultKind:", o.get('resultKind'), "reason:", o.get('reason')); break
# which tool names occur in the orchestrator-ish files
import collections
names=collections.Counter()
for f in glob.glob('*.jsonl'):
    for line in open(f, errors='replace'):
        if '"tool_use"' not in line: continue
        try:o=json.loads(line)
        except: continue
